query GalaxyFlowsDrawerGetFlowDataQuery($request) {
  xwa_extensions_get_flow_data {
    __typename
    extensions_flow_data {
      flow_id
      extensions {
        metadata {
          flow_name
          state
          categories
          creation_source
          www_proxy_secret
          flow_token_signature
          endpoint_public_key {
            key
            signature
          }
        }
      }
    }
  }
}
